import{_ as p,r as n,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Запросы модели - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Получение нескольких моделей","slug":"получение-нескольких-моделеи","link":"#получение-нескольких-моделеи","children":[{"level":3,"title":"Доступ к значениям столбцов","slug":"доступ-к-значениям-столбцов","link":"#доступ-к-значениям-столбцов","children":[]},{"level":3,"title":"Добавление дополнительных ограничений","slug":"добавление-дополнительных-ограничении","link":"#добавление-дополнительных-ограничении","children":[]},{"level":3,"title":"Коллекции","slug":"коллекции","link":"#коллекции","children":[]},{"level":3,"title":"Разбиение результатов на части","slug":"разбиение-результатов-на-части","link":"#разбиение-результатов-на-части","children":[]}]},{"level":2,"title":"Получение одной модели","slug":"получение-однои-модели","link":"#получение-однои-модели","children":[{"level":3,"title":"Исключения «Не найдено»","slug":"исключения-«не-наидено»","link":"#исключения-«не-наидено»","children":[]},{"level":3,"title":"Получение агрегатов","slug":"получение-агрегатов","link":"#получение-агрегатов","children":[]}]},{"level":2,"title":"Вставка и обновление моделей","slug":"вставка-и-обновление-моделеи","link":"#вставка-и-обновление-моделеи","children":[{"level":3,"title":"Базовая вставка","slug":"базовая-вставка","link":"#базовая-вставка","children":[]},{"level":3,"title":"Базовое обновление","slug":"базовое-обновление","link":"#базовое-обновление","children":[]},{"level":3,"title":"Массовое присваивание","slug":"массовое-присваивание","link":"#массовое-присваивание","children":[]},{"level":3,"title":"Другие методы создания","slug":"другие-методы-создания","link":"#другие-методы-создания","children":[]}]},{"level":2,"title":"Удаление моделей","slug":"удаление-моделеи","link":"#удаление-моделеи","children":[]},{"level":2,"title":"Области запросов","slug":"области-запросов","link":"#области-запросов","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/extend/database/model.md","filePath":"3.x/ru/extend/database/model.md"}'),u={name:"3.x/ru/extend/database/model.md"};function r(k,s,d,g,h,f){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[a(t),s[0]||(s[0]=l("h1",null,"Запросы модели",-1)),a(e),s[1]||(s[1]=i(`<p>При запросе данных из базы данных модель получает значения в первую очередь с помощью методов <code>get</code> или <code>first</code>, в зависимости от того, хотите ли вы получить несколько моделей или одну модель соответственно. Запросы, производные от модели, возвращают экземпляр <code>October\\Rain\\Database\\Builder</code>.</p><h2 id="получение-нескольких-моделеи"><a href="#получение-нескольких-моделеи" class="header-anchor">#</a> Получение нескольких моделей</h2><p>После создания модели и <a href="./structure.html">соответствующей таблицы базы данных</a> вы готовы начать получать данные из базы данных. Представьте каждую модель как мощный <a href="./query.html">конструктор запросов</a>, позволяющий запрашивать таблицу базы данных, связанную с моделью.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flights</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="доступ-к-значениям-столбцов"><a href="#доступ-к-значениям-столбцов" class="header-anchor">#</a> Доступ к значениям столбцов</h3><p>Если у вас есть экземпляр модели, вы можете получить доступ к значениям столбцов модели, обращаясь к соответствующему свойству. Например, давайте пройдём по каждому экземпляру <code>Flight</code>, возвращённому нашим запросом, и выведем значение столбца <code>name</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$flights</span> <span class="token keyword">as</span> <span class="token variable">$flight</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="добавление-дополнительных-ограничении"><a href="#добавление-дополнительных-ограничении" class="header-anchor">#</a> Добавление дополнительных ограничений</h3><p>Метод <code>all</code> вернёт все результаты из таблицы модели. Поскольку каждая модель служит <a href="./query.html">конструктором запросов</a>, вы также можете добавлять ограничения к запросам, а затем использовать метод <code>get</code> для получения результатов:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flights</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;desc&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">take</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Поскольку модели являются конструкторами запросов, вам следует ознакомиться со всеми доступными методами <a href="./query.html">конструктора запросов</a>. Вы можете использовать любой из этих методов в запросах модели.</p></div><h3 id="коллекции"><a href="#коллекции" class="header-anchor">#</a> Коллекции</h3><p>Для методов, таких как <code>all</code> и <code>get</code>, которые возвращают несколько результатов, будет возвращён экземпляр <code>Collection</code>. Этот класс предоставляет <a href="./collection.html">множество полезных методов</a> для работы с вашими результатами. Конечно, вы можете просто перебирать эту коллекцию как массив.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$flights</span> <span class="token keyword">as</span> <span class="token variable">$flight</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="разбиение-результатов-на-части"><a href="#разбиение-результатов-на-части" class="header-anchor">#</a> Разбиение результатов на части</h3><p>Если вам нужно обработать тысячи записей, используйте команду <code>chunk</code>. Метод <code>chunk</code> получит «часть» моделей, передавая их заданному <code>Closure</code> для обработки. Использование метода <code>chunk</code> позволяет экономить память при работе с большими наборами результатов.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">chunk</span><span class="token punctuation">(</span><span class="token number">200</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$flights</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$flights</span> <span class="token keyword">as</span> <span class="token variable">$flight</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">//</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Первый аргумент, передаваемый методу — это количество записей, которые вы хотите получить на каждую «часть». Closure, передаваемое в качестве второго аргумента, будет вызвано для каждой части, полученной из базы данных.</p><h2 id="получение-однои-модели"><a href="#получение-однои-модели" class="header-anchor">#</a> Получение одной модели</h2><p>Помимо получения всех записей для данной таблицы, вы также можете получить отдельные записи с помощью <code>find</code> и <code>first</code>. Вместо коллекции моделей эти методы возвращают один экземпляр модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Retrieve a model by its primary key</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Retrieve the first model matching the query constraints</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="исключения-«не-наидено»"><a href="#исключения-«не-наидено»" class="header-anchor">#</a> Исключения «Не найдено»</h3><p>Иногда вы можете захотеть выбросить исключение, если модель не найдена. Это особенно полезно в маршрутах или контроллерах. Методы <code>findOrFail</code> и <code>firstOrFail</code> получат первый результат запроса. Однако, если результат не найден, будет выброшено исключение <code>Illuminate\\Database\\Eloquent\\ModelNotFoundException</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">findOrFail</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$model</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;legs&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">firstOrFail</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>При <a href="./../system/routing.html">разработке API</a>, если исключение не перехвачено, HTTP-ответ <code>404</code> автоматически отправляется обратно пользователю, поэтому нет необходимости писать явные проверки для возврата ответов <code>404</code> при использовании этих методов.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/api/flights/{id}&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">findOrFail</span><span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="получение-агрегатов"><a href="#получение-агрегатов" class="header-anchor">#</a> Получение агрегатов</h3><p>Вы также можете использовать <code>count</code>, <code>sum</code>, <code>max</code> и другие <a href="./query.html">агрегатные функции</a>, предоставляемые конструктором запросов. Эти методы возвращают соответствующее скалярное значение вместо полного экземпляра модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$count</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$max</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;price&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="вставка-и-обновление-моделеи"><a href="#вставка-и-обновление-моделеи" class="header-anchor">#</a> Вставка и обновление моделей</h2><p>Вставка и обновление данных — это основная функция моделей, она делает процесс простым по сравнению с традиционными SQL-операторами.</p><h3 id="базовая-вставка"><a href="#базовая-вставка" class="header-anchor">#</a> Базовая вставка</h3><p>Для создания новой записи в базе данных просто создайте новый экземпляр модели, установите атрибуты модели, затем вызовите метод <code>save</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Flight</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Sydney to Canberra&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В этом примере мы просто создаём новый экземпляр модели <code>Flight</code> и присваиваем атрибут <code>name</code>. При вызове метода <code>save</code> запись будет вставлена в базу данных. Временные метки <code>created_at</code> и <code>updated_at</code> также будут автоматически установлены, поэтому нет необходимости устанавливать их вручную.</p><h3 id="базовое-обновление"><a href="#базовое-обновление" class="header-anchor">#</a> Базовое обновление</h3><p>Метод <code>save</code> может также использоваться для обновления моделей, которые уже существуют в базе данных. Для обновления модели вы должны получить её, установить любые атрибуты, которые хотите обновить, а затем вызвать метод <code>save</code>. Опять же, временная метка <code>updated_at</code> будет автоматически обновлена, поэтому нет необходимости вручную устанавливать её значение:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Darwin to Adelaide&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Обновления также могут быть выполнены для любого количества моделей, соответствующих данному запросу. В этом примере все рейсы, которые <code>active</code> и имеют <code>destination</code> равный <code>San Diego</code>, будут отмечены как задержанные:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;destination&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Perth&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;delayed&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>update</code> ожидает массив пар столбцов и значений, представляющих столбцы, которые должны быть обновлены.</p><h3 id="массовое-присваивание"><a href="#массовое-присваивание" class="header-anchor">#</a> Массовое присваивание</h3><p>Вы также можете использовать метод <code>create</code> для сохранения новой модели в одну строку. Вставленный экземпляр модели будет возвращён вам из метода. Однако перед этим вам необходимо указать свойство <code>fillable</code> или <code>guarded</code> в модели, так как все модели защищены от массового присваивания. Обратите внимание, что ни <code>fillable</code>, ни <code>guarded</code> не влияют на отправку форм панели управления, а только на использование метода <code>create</code> или <code>fill</code>.</p><p>Уязвимость массового присваивания возникает, когда пользователь передаёт неожиданный HTTP-параметр через запрос, и этот параметр изменяет столбец в вашей базе данных, который вы не ожидали. Например, злоумышленник может отправить параметр <code>is_admin</code> через HTTP-запрос, который затем передаётся в метод <code>create</code> вашей модели, позволяя пользователю повысить себя до администратора.</p><p>Для начала вы должны определить, какие атрибуты модели вы хотите сделать доступными для массового присваивания. Вы можете сделать это с помощью свойства <code>$fillable</code> модели. Например, сделаем атрибут <code>name</code> нашей модели <code>Flight</code> доступным для массового присваивания:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Flight</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var array fillable attributes that are mass assignable.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$fillable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>После того как мы сделали атрибуты доступными для массового присваивания, мы можем использовать метод <code>create</code> для вставки новой записи в базу данных. Метод <code>create</code> возвращает сохранённый экземпляр модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В то время как <code>$fillable</code> служит «белым списком» атрибутов, доступных для массового присваивания, вы также можете использовать <code>$guarded</code>. Свойство <code>$guarded</code> должно содержать массив атрибутов, которые вы не хотите делать доступными для массового присваивания. Все остальные атрибуты, не входящие в массив, будут доступны для массового присваивания. Таким образом, <code>$guarded</code> функционирует как «чёрный список». Конечно, вы должны использовать либо <code>$fillable</code>, либо <code>$guarded</code> — не оба:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Flight</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * The attributes that aren&#39;t mass assignable.
     *
     * @var array
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$guarded</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;price&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>В приведённом выше примере все атрибуты, <strong>кроме <code>price</code></strong>, будут доступны для массового присваивания.</p><h3 id="другие-методы-создания"><a href="#другие-методы-создания" class="header-anchor">#</a> Другие методы создания</h3><p>Иногда вы можете захотеть только создать новый экземпляр модели. Вы можете сделать это с помощью метода <code>make</code>. Метод <code>make</code> просто вернёт новый экземпляр без сохранения или создания чего-либо.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Functionally the same as...</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Flight</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">fill</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Есть ещё два метода, которые вы можете использовать для создания моделей путём массового присваивания атрибутов: <code>firstOrCreate</code> и <code>firstOrNew</code>. Метод <code>firstOrCreate</code> попытается найти запись в базе данных, используя заданные пары столбец/значение. Если модель не может быть найдена в базе данных, будет вставлена запись с заданными атрибутами.</p><p>Метод <code>firstOrNew</code>, как и <code>firstOrCreate</code>, попытается найти запись в базе данных, соответствующую заданным атрибутам. Однако, если модель не найдена, будет возвращён новый экземпляр модели. Обратите внимание, что модель, возвращённая <code>firstOrNew</code>, ещё не сохранена в базе данных. Вам нужно будет вызвать <code>save</code> вручную для её сохранения:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Retrieve the flight by the attributes, otherwise create it</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">firstOrCreate</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Retrieve the flight by the attributes, or instantiate a new instance</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">firstOrNew</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="удаление-моделеи"><a href="#удаление-моделеи" class="header-anchor">#</a> Удаление моделей</h2><p>Для удаления модели вызовите метод <code>delete</code> на экземпляре модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В приведённом выше примере мы получаем модель из базы данных перед вызовом метода <code>delete</code>. Однако, если вы знаете первичный ключ модели, вы можете удалить модель без её предварительного получения. Для этого вызовите метод <code>destroy</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">destroy</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">destroy</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">destroy</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете выполнить запрос на удаление для набора моделей. В этом примере мы удалим все рейсы, отмеченные как неактивные:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$deletedRows</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>Важно отметить, что <a href="./../system/models.html">события модели</a> не будут вызваны при удалении записей напрямую из запроса.</p></div><h2 id="области-запросов"><a href="#области-запросов" class="header-anchor">#</a> Области запросов</h2><p>Области позволяют вам определять общие наборы ограничений, которые вы можете легко повторно использовать в приложении. Например, вам может часто требоваться получить всех пользователей, которые считаются «популярными». Для определения области просто добавьте префикс <code>scope</code> к методу модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * scopePopular query to only include popular users.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopePopular</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * scopeActive query to only include active users.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeActive</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>После определения области вы можете вызывать методы области при запросе модели. Однако вам не нужно включать префикс <code>scope</code> при вызове метода. Вы можете даже объединять вызовы различных областей, например:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">popular</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">active</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Иногда вы можете захотеть определить область, принимающую параметры. Для начала просто добавьте дополнительные параметры к вашей области. Параметры области должны быть определены после аргумента <code>$query</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * Scope a query to only include users of a given type.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeApplyType</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Теперь вы можете передавать параметры при вызове области:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">applyType</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../system/models.html">Статья о моделях</a></li></ul></div>`,76))])}const b=p(u,[["render",r]]);export{v as __pageData,b as default};
